/// Appends the gh-210 level-0 blocks at the context tail: the
/// obligations ledger first (issue #1380), then the bounded working-set
/// block (the goal recitation + the touched-file references) as the
/// tail-most message. Both are additive projection output — neither is
/// ever written as a session record, so every hide path (judge,

  for (final record in path) {
    if (record is! MessageRecord) continue;
    final message = record.message;
    if (message is! AssistantMessage) continue;
    for (final block in message.content) {
      if (block is! ToolCall || !workingSetWriteTools.contains(block.name)) {
        continue;
      }
      final argument = block.arguments['path'];
      if (argument is! String) continue;
      // One line per fact (the goal line's rule): a `\n` is legal in
      // POSIX filenames and model-emittable into tool arguments — verbatim
      // rendering would inject block structure (fake entries, fake
      // counting tails) into the system-tagged block. Whitespace
      // collapses here so the render and the budgets measure the final
      // strings, and spelling dedup stays consistent.
      final flattened = argument.replaceAll(RegExp(r'\s+'), ' ').trim();
      if (flattened.isEmpty) continue;
      lastMention[flattened] = i++;
    }
  }
  final paths = lastMention.keys.toList()
    ..sort((a, b) => lastMention[a]!.compareTo(lastMention[b]!));
  return paths;
}

/// Whether [path] carries a compaction boundary — a structured hide, a
/// structured checkpoint, or a classic compaction record. The files
/// section of the working set renders only past one (post-compact
/// re-injection; pre-compaction the content is still in context).
bool hasCompactionBoundary(List<SessionRecord> path) => path.any(
  (record) =>
      record is HiddenRangeRecord ||
      record is CompactCheckpointRecord ||
      record is CompactionRecord,
